'use strict';
(function(root){const content={"version": 1, "notice": "Original, unofficial IELTS-style practice. Scenarios, organisations and study results in these passages are fictional. Format follows published IELTS guidance; difficulty and scores are not calibrated. These are not past-paper questions and cannot establish an IELTS band.", "reading": [{"id": "reading-cooler-route-v1", "title": "A cooler route to school", "level": "Academic practice — uncalibrated", "paragraphs": [{"label": "A", "text": "A city council wanted to make walking to school more attractive during warm weather. Instead of immediately planting trees along every route, its planners first asked where additional shade might make the greatest difference. They selected twelve streets near four schools and measured air temperature at child height. Each street was observed at the same three times on five dry weekdays. Volunteers also counted pedestrians, but they did not record individual identities or follow particular children."}, {"label": "B", "text": "The shaded streets were, on average, cooler at lunchtime than streets with little shade. Yet this comparison could not establish that trees alone explained the difference. The shaded streets also tended to have fewer parked cars and more gardens. In addition, the instruments measured air temperature rather than the temperature of the pavement or the amount of sunlight reaching a walker. Those other measures might have helped explain how comfortable each route felt. The report therefore described an association, not a controlled test of the effect of trees."}, {"label": "C", "text": "A separate questionnaire asked pupils to choose between two routes shown on a simple map. One was shorter and exposed to the sun; the other took four minutes longer but included shade. Most respondents preferred the shaded route in hot weather. However, when the same choice was presented for a rainy morning, the shorter route became more popular. The questionnaires measured stated preferences. They did not establish which route pupils actually used, or whether a parent would allow them to take a different one."}, {"label": "D", "text": "The council decided to trial temporary shade at two busy waiting points before making a larger investment. These locations were chosen because pupils sometimes stood there for several minutes, rather than because they were the hottest places in the survey. To assess the trial, staff would compare conditions before and after installation and retain two similar waiting points without new shade. They would also record weather conditions throughout the comparison period. The planners acknowledged that temporary structures could not reproduce every benefit of a mature tree. Their immediate question was narrower: could a modest change make an existing walk more comfortable while the council considered a longer planting programme?"}], "questions": [{"id": "r1q1", "type": "tfng", "prompt": "All twelve streets were observed at the same three times.", "answer": "True", "explanation": "A: each street was measured at the same three times on five days.", "skill": "identifying information", "options": ["True", "False", "Not given"]}, {"id": "r1q2", "type": "tfng", "prompt": "The measurements proved that trees alone caused the temperature difference.", "answer": "False", "explanation": "B explicitly says the comparison could not establish that trees alone explained the difference.", "skill": "causal claims", "options": ["True", "False", "Not given"]}, {"id": "r1q3", "type": "tfng", "prompt": "Parents completed the route questionnaire alongside the pupils.", "answer": "Not given", "explanation": "C describes pupils answering; it gives no information about parents completing the questionnaire.", "skill": "not given", "options": ["True", "False", "Not given"]}, {"id": "r1q4", "type": "mcq", "prompt": "Why does the writer distinguish stated preferences from actual routes?", "answer": "What pupils say they prefer may differ from what they do.", "explanation": "C says the questionnaires did not establish which route pupils used.", "skill": "inference", "options": ["Pupils were unable to understand the map.", "What pupils say they prefer may differ from what they do.", "All pupils already walked along the shorter route.", "Parents were asked to choose the longest route."]}, {"id": "r1q5", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from the passage: The trial installed shade at two busy _____.", "answer": "waiting points", "explanation": "D names the selected locations as waiting points.", "skill": "word-limited completion", "maxWords": 2}, {"id": "r1q6", "type": "headings", "prompt": "Choose the best heading for paragraph D.", "answer": "Testing a limited change before a larger commitment", "explanation": "D describes a small trial and how it will be assessed before a larger planting programme.", "skill": "main idea", "options": ["The disappearance of all differences between routes", "Testing a limited change before a larger commitment", "Why children must always choose the shortest route", "Replacing temperature measurements with opinions", "A history of the city’s school buildings"]}], "wordCount": 357}, {"id": "reading-library-v1", "title": "When a library lends more than books", "level": "Academic practice — uncalibrated", "paragraphs": [{"label": "A", "text": "The North Quay library began lending tools after a local survey revealed an unexpected pattern. Residents said they frequently postponed small repairs because they lacked equipment they would use only once or twice. Buying such equipment seemed expensive, while borrowing informally depended on knowing a neighbour who owned it. The library already had a booking system and staff experienced in managing shared resources, so the council approved a small trial rather than creating a new organisation."}, {"label": "B", "text": "The initial collection included drills, sewing machines and basic gardening equipment. Staff rejected a proposal to include ladders because they could not store them safely in the available room. Storage, rather than price, determined that decision. Before adding an item, they considered not only its purchase price but also the time needed to inspect it, replace missing parts and explain its use. Every borrower received a short safety guide. Some tools required an introductory demonstration, although borrowers did not have to attend a general training course before joining the scheme."}, {"label": "C", "text": "After six months, the library reported 420 loans. This was a useful measure of activity, but it was not the number of people who had benefited: several borrowers had taken out multiple tools. Nor could the figure show how many purchases had been avoided. Someone borrowing a drill might otherwise have hired one, asked a friend for help or abandoned the repair. The project team therefore added a voluntary question asking what borrowers would probably have done without the service. Such answers remained estimates rather than observations of an alternative reality."}, {"label": "D", "text": "The trial also exposed an imbalance. Lightweight items were borrowed regularly, while heavier equipment was less popular. Interviews suggested that carrying a tool home was a barrier for residents who walked or used buses. In response, the library introduced a small delivery service on two afternoons each week. Its first evaluation would compare changes in borrowing across different item categories, rather than simply celebrate any increase in total loans."}, {"label": "E", "text": "For the manager, the scheme’s value lay in making practical resources accessible, not in turning the library into the largest possible store of equipment. She argued that a small, reliable collection could be more useful than a much bigger one that was difficult to maintain. The next purchasing round would therefore prioritise repairs and replacements before adding unfamiliar categories."}], "questions": [{"id": "r2q1", "type": "tfng", "prompt": "Residents sometimes delayed repairs because they did not own the necessary tools.", "answer": "True", "explanation": "A states that residents postponed repairs because they lacked equipment.", "skill": "paraphrase", "options": ["True", "False", "Not given"]}, {"id": "r2q2", "type": "tfng", "prompt": "Ladders were excluded because their purchase price was too high.", "answer": "False", "explanation": "B gives unsafe storage in the available room as the reason, rather than purchase cost.", "skill": "contradiction", "options": ["True", "False", "Not given"]}, {"id": "r2q3", "type": "completion", "prompt": "Complete with ONE WORD from paragraph B: Every borrower received a short safety _____.", "answer": "guide", "explanation": "B states that every borrower received a safety guide.", "skill": "word-limited completion", "maxWords": 1}, {"id": "r2q4", "type": "mcq", "prompt": "Why were 420 loans insufficient to show the number of purchases avoided?", "answer": "Borrowers might have used several different alternatives.", "explanation": "C lists hiring, asking a friend and abandoning the repair as alternatives to buying.", "skill": "reasoning", "options": ["Every loan necessarily replaced a purchase.", "The library had lost all its records.", "Borrowers might have used several different alternatives.", "Only purchases of gardening tools were counted."]}, {"id": "r2q5", "type": "headings", "prompt": "Choose the best heading for paragraph D.", "answer": "Addressing a practical obstacle to borrowing", "explanation": "D identifies transport as a barrier and introduces delivery in response.", "skill": "main idea", "options": ["Replacing interviews with purchase records", "Addressing a practical obstacle to borrowing", "Closing a collection that nobody uses", "Making every item the same weight", "The origins of the library building"]}, {"id": "r2q6", "type": "tfng", "prompt": "The delivery service was funded by a local bus company.", "answer": "Not given", "explanation": "D describes when delivery operates but does not identify its funder.", "skill": "not given", "options": ["True", "False", "Not given"]}], "wordCount": 385}, {"id": "reading-memory-v1", "title": "The usefulness of a difficult question", "level": "Academic practice — uncalibrated", "paragraphs": [{"label": "A", "text": "A student rereads a page and recognises every sentence. The experience feels reassuring, but recognition does not necessarily show that the student could explain the ideas tomorrow without seeing the page. For that reason, I argue that a useful learning session should include an opportunity to retrieve an idea before looking at it again. The opportunity need not be an examination. A question answered privately, with no mark attached, can reveal a gap that fluent rereading conceals."}, {"label": "B", "text": "This is not an argument for making every task difficult. A question that depends on several unfamiliar concepts may produce little more than random guessing. When that happens, a brief explanation or a worked example can provide a foundation for a more manageable attempt. The important distinction is between difficulty that prompts meaningful thinking and difficulty that gives the learner no workable starting point. Treating all effort as equally productive obscures that distinction and can make an activity feel needlessly punishing."}, {"label": "C", "text": "Consider two follow-up questions after a short explanation of food chains. One asks the learner to repeat the definition of a producer that appeared in the final sentence. The other describes a simple unfamiliar ecosystem and asks which organism fills that role. The second question requires the idea to be applied beyond its original wording. It therefore supplies different evidence. However, an immediate correct application still does not establish that the idea will remain available after a week. The timing and context of a successful response matter as well as its correctness."}, {"label": "D", "text": "Feedback should help the learner decide what to do next. Showing only a red cross leaves too much work unspecified, while displaying a complete answer too quickly can remove the very thinking the activity was designed to encourage. A limited hint can be useful when it points attention towards a relevant relationship without settling the answer. After feedback, the learner can try a new example, but this supported success should be recorded separately from a later independent response."}, {"label": "E", "text": "For these reasons, I would resist a dashboard that labels an entire topic mastered after one correct multiple-choice answer. That label promises more than the evidence supports. A better record can celebrate that a learner completed a block, corrected a misunderstanding or later recalled an idea independently. Such achievements are modest enough to be credible and meaningful enough to show progress. Encouragement need not depend on exaggerated claims."}], "questions": [{"id": "r3q1", "type": "ynng", "prompt": "The writer believes recognition during rereading always proves durable knowledge.", "answer": "No", "explanation": "A says recognition does not necessarily show the ability to explain the ideas tomorrow.", "skill": "writer claims", "options": ["Yes", "No", "Not given"]}, {"id": "r3q2", "type": "ynng", "prompt": "The writer supports questions that let learners identify gaps without receiving a mark.", "answer": "Yes", "explanation": "A explicitly supports private, unmarked questions that reveal gaps.", "skill": "writer claims", "options": ["Yes", "No", "Not given"]}, {"id": "r3q3", "type": "ynng", "prompt": "The writer thinks paper questionnaires are more effective than digital ones.", "answer": "Not given", "explanation": "No comparison of paper and digital formats is made.", "skill": "not given", "options": ["Yes", "No", "Not given"]}, {"id": "r3q4", "type": "mcq", "prompt": "What is the main difference between the two food-chain questions?", "answer": "One requires application in a new setting.", "explanation": "C contrasts repeating wording with applying the idea in an unfamiliar ecosystem.", "skill": "comparison", "options": ["One requires application in a new setting.", "Only one can ever be answered correctly.", "One measures recall after a week.", "The first uses an unfamiliar ecosystem."]}, {"id": "r3q5", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from paragraph D: A useful hint directs attention towards a relevant _____.", "answer": "relationship", "explanation": "D describes directing attention to a relevant relationship without settling the answer.", "skill": "word-limited completion", "maxWords": 2}, {"id": "r3q6", "type": "headings", "prompt": "Choose the best heading for paragraph E.", "answer": "Recognising progress without overstating it", "explanation": "E argues for credible achievements instead of declaring mastery from one response.", "skill": "main idea", "options": ["Why all learning records should be removed", "Recognising progress without overstating it", "A comparison of competing dashboard prices", "Why encouragement prevents independent thinking", "How to memorise an answer key"]}], "wordCount": 396}, {"id": "reading-repair-v1", "title": "Designing products for a second life", "level": "Academic practice — uncalibrated", "paragraphs": [{"label": "A", "text": "When a small manufacturer redesigned its desk lamp, the development team initially focused on reducing the amount of material in the base. A lighter base would use less metal and cost less to transport. However, interviews with repair technicians changed the discussion. The technicians rarely replaced a damaged base. Their most common difficulty was opening the lamp without breaking the clips that held its casing together. A product could be material-efficient at manufacture yet still become waste after a minor failure."}, {"label": "B", "text": "The next prototype replaced the clips with four standard screws. It also separated the power cable from the internal lighting unit, allowing either part to be removed independently. These alterations added a little weight and increased the assembly time. The team accepted those disadvantages because the design made common repairs easier. It did not claim that every environmental impact had been reduced; the benefits depended partly on whether owners actually repaired their lamps and continued to use them."}, {"label": "C", "text": "To investigate that question, the manufacturer gave repair shops written instructions and guaranteed access to replacement cables for five years. It then recorded repairs completed through those shops. The records showed that cable replacement was the most common intervention during the first year. Yet the records did not include repairs made at home or lamps that owners threw away without seeking advice. The results described the activity of participating shops, not the fate of every lamp sold."}, {"label": "D", "text": "Price was another constraint. A repair that required an inexpensive part could still be costly once labour and transport were included. The manufacturer therefore introduced a detachable cable in its third prototype, so that owners could replace it without opening the casing. Electrical components inside the lamp remained a job for qualified repairers. The instruction leaflet distinguished those two tasks clearly rather than treating all repair as equally suitable for an inexperienced owner."}, {"label": "E", "text": "The project illustrates a tension in product design. Reducing material, extending useful life and keeping an item affordable can support one another, but they do not always do so automatically. Evaluating just one characteristic may reward a change that creates difficulties elsewhere. For the team, the lesson was to define the intended benefit precisely and measure the behaviour on which that benefit depended. A lamp designed to be repaired is an opportunity; a lamp that is repaired and used for longer is an observed outcome."}], "questions": [{"id": "r4q1", "type": "tfng", "prompt": "Repair technicians most often needed to replace the lamp’s base.", "answer": "False", "explanation": "A says they rarely replaced the base; opening the casing was the common problem.", "skill": "frequency and quantifiers", "options": ["True", "False", "Not given"]}, {"id": "r4q2", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from paragraph B: The second design held the casing together with four _____.", "answer": "standard screws", "explanation": "B states that the clips were replaced with four standard screws.", "skill": "word-limited completion", "maxWords": 2}, {"id": "r4q3", "type": "tfng", "prompt": "The second prototype was lighter than the first design.", "answer": "False", "explanation": "B says the alterations added a little weight.", "skill": "comparisons", "options": ["True", "False", "Not given"]}, {"id": "r4q4", "type": "tfng", "prompt": "The manufacturer paid owners for every lamp they repaired.", "answer": "Not given", "explanation": "The passage discusses repair records, access and cost, but says nothing about payments to owners.", "skill": "not given", "options": ["True", "False", "Not given"]}, {"id": "r4q5", "type": "headings", "prompt": "Choose the best heading for paragraph D.", "answer": "Making a specific repair more accessible", "explanation": "D explains why a detachable cable reduced one barrier while internal electrical work remained specialist.", "skill": "main idea", "options": ["Making a specific repair more accessible", "Replacing all qualified repair technicians", "Proving that transport has no cost", "How lamps first became popular", "Why a guarantee prevents every failure"]}, {"id": "r4q6", "type": "mcq", "prompt": "Which distinction is central to the final paragraph?", "answer": "A design possibility differs from an outcome that actually occurs.", "explanation": "E contrasts being designed for repair with actually being repaired and used for longer.", "skill": "inference", "options": ["Every lightweight design is affordable.", "Any repair automatically reduces every impact.", "A design possibility differs from an outcome that actually occurs.", "Observed behaviour is less useful than the product’s colour."]}], "wordCount": 394}, {"id": "reading-museum-v1", "title": "Whose labels tell the story?", "level": "Academic practice — uncalibrated", "paragraphs": [{"label": "A", "text": "A regional museum once described objects mainly through their date, material and place of manufacture. When it renewed a gallery, its curators invited local residents to suggest additional information. An ordinary cooking pot, for example, prompted accounts of family meals, shortages and migration. Those memories did not replace the object’s physical description. They offered another route into its significance, especially for visitors who found specialist terms unfamiliar or unhelpful."}, {"label": "B", "text": "Some critics worried that personal accounts would displace reliable historical information. I think that concern is reasonable when memories are presented as unquestionable facts, but it does not justify excluding them altogether. A memory can be identified as one person’s recollection and placed beside documentary evidence. If the two conflict, the disagreement can itself become part of the interpretation. Visitors need to know what kind of evidence they are seeing and what it can reasonably establish."}, {"label": "C", "text": "Selection remains unavoidable. A small label cannot contain every story, and the residents who attend consultation meetings do not necessarily represent everyone connected with an object. In this project, daytime meetings initially attracted mainly retired participants. The museum later added evening sessions and invited written contributions. These changes widened the available opportunities, although the museum did not claim that every relevant perspective had finally been included. An invitation is not the same thing as universal participation."}, {"label": "D", "text": "The resulting labels used a layered design. A short opening statement introduced the object, a second section presented a personal account, and a final line directed interested visitors to additional evidence. The aim was to allow different levels of engagement without forcing every reader through a long text. Staff observed how visitors moved through the gallery and asked a sample what they remembered. They did not assume that time spent standing in front of a label was, by itself, proof of understanding."}, {"label": "E", "text": "I would judge this approach by whether it makes the museum’s choices and evidence easier to examine, rather than by whether every visitor agrees with the interpretation. A museum cannot avoid shaping a story simply by using a neutral tone. Choosing one date, one event or one technical name already directs attention. Making those choices visible may support a more thoughtful relationship with the past, provided that personal voices and historical claims are clearly distinguished."}], "questions": [{"id": "r5q1", "type": "ynng", "prompt": "The writer believes personal memories should be excluded whenever they differ from documents.", "answer": "No", "explanation": "B says disagreements can become part of interpretation instead of automatically excluding memories.", "skill": "writer claims", "options": ["Yes", "No", "Not given"]}, {"id": "r5q2", "type": "ynng", "prompt": "The writer thinks visitors should be told what kind of evidence a label presents.", "answer": "Yes", "explanation": "B states that visitors need to know what kind of evidence they are seeing.", "skill": "writer claims", "options": ["Yes", "No", "Not given"]}, {"id": "r5q3", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from paragraph C: Early daytime meetings mainly attracted _____.", "answer": "retired participants", "explanation": "C identifies the group that mainly attended the first daytime meetings.", "skill": "word-limited completion", "maxWords": 2}, {"id": "r5q4", "type": "headings", "prompt": "Choose the best heading for paragraph D.", "answer": "Offering several depths of engagement", "explanation": "D describes layers of information and checks of what visitors remembered.", "skill": "main idea", "options": ["Why all labels must contain the same number of words", "Offering several depths of engagement", "Abandoning observation of visitors", "A new method of manufacturing cooking pots", "Replacing evidence with entertainment"]}, {"id": "r5q5", "type": "ynng", "prompt": "The writer believes a neutral tone guarantees that a museum has avoided shaping a story.", "answer": "No", "explanation": "E explicitly rejects that claim: selection still directs attention.", "skill": "writer claims", "options": ["Yes", "No", "Not given"]}, {"id": "r5q6", "type": "ynng", "prompt": "The writer believes every regional museum should charge an entrance fee.", "answer": "Not given", "explanation": "There is no view expressed about entrance fees.", "skill": "not given", "options": ["Yes", "No", "Not given"]}], "wordCount": 378}, {"id": "reading-bus-data-v1", "title": "When the average bus is on time", "level": "Academic practice — uncalibrated", "paragraphs": [{"label": "A", "text": "A transport operator announced that its buses had become more punctual after a timetable change. Across the whole network, the proportion of arrivals within the published tolerance rose from 78 per cent to 84 per cent. The improvement was real in the recorded data, but a passenger group wanted to know whether it described the journeys people depended on most. A network average combined busy commuter routes with quieter services and could conceal differences between them."}, {"label": "B", "text": "The operator originally counted each recorded arrival equally. A late bus carrying sixty passengers therefore contributed no more to the statistic than a late bus carrying six. Passenger-weighted figures would answer a different question by giving more influence to heavily used services. Neither measure was automatically wrong. The first described the reliability of scheduled bus movements; the second was closer to describing how many passenger journeys were affected. Confusion arose when a figure answering the first question was presented as if it answered both."}, {"label": "C", "text": "The group also asked for results by time of day. Morning services had become more reliable, while evening reliability had fallen slightly. The new timetable had added running time to the morning schedule but made no comparable adjustment in the evening. That pattern suggested a possible explanation for the difference, although it did not rule out changing traffic conditions or temporary roadworks. The data did not establish which of those influences mattered most."}, {"label": "D", "text": "A further complication concerned missing records. Some vehicle tracking units failed to transmit information on certain days. The operator excluded those arrivals from the calculation and published the proportion of missing records alongside the results. If missing data were concentrated on unusually disrupted days, the reported reliability could be misleadingly high. If they were spread evenly, the effect might be much smaller. Knowing that data are missing is useful; knowing why they are missing is more informative."}, {"label": "E", "text": "The operator eventually published a small dashboard with separate views for routes, time periods and passenger-weighted performance. It retained the network average as an overview but added a clear description of what was counted. The passenger group welcomed the change without claiming that additional statistics had made the buses faster. Better measurement can clarify a problem and guide action, but it is not itself the service improvement that travellers ultimately want."}], "questions": [{"id": "r6q1", "type": "tfng", "prompt": "The operator’s original calculation gave each recorded arrival equal importance.", "answer": "True", "explanation": "B explicitly states that each recorded arrival was counted equally.", "skill": "identifying information", "options": ["True", "False", "Not given"]}, {"id": "r6q2", "type": "tfng", "prompt": "Evening reliability improved after the timetable change.", "answer": "False", "explanation": "C says evening reliability fell slightly.", "skill": "contradiction", "options": ["True", "False", "Not given"]}, {"id": "r6q3", "type": "tfng", "prompt": "Roadworks were proved to be the largest cause of delays.", "answer": "False", "explanation": "C states that the data did not establish which influence mattered most.", "skill": "certainty", "options": ["True", "False", "Not given"]}, {"id": "r6q4", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from paragraph D: Some missing records resulted from failures of vehicle _____.", "answer": "tracking units", "explanation": "D identifies the tracking units that failed to transmit.", "skill": "word-limited completion", "maxWords": 2}, {"id": "r6q5", "type": "headings", "prompt": "Choose the best heading for paragraph B.", "answer": "Two legitimate measures answering different questions", "explanation": "B compares counting bus movements with weighting passenger journeys.", "skill": "main idea", "options": ["Why all buses should carry sixty people", "Two legitimate measures answering different questions", "A reliable method of predicting roadworks", "Eliminating every evening service", "The cost of replacing tracking equipment"]}, {"id": "r6q6", "type": "mcq", "prompt": "What does the final paragraph emphasise?", "answer": "Improved information is useful but does not itself improve travel.", "explanation": "E distinguishes clearer measurement from faster buses or better service.", "skill": "overall argument", "options": ["Publishing more data automatically makes buses faster.", "The network average should never be used.", "Improved information is useful but does not itself improve travel.", "Passenger groups should stop examining timetables."]}], "wordCount": 381}], "readingFull": {"id": "academic-reading-full-v1", "title": "Academic Reading — full section practice", "level": "Full-length format; original and uncalibrated", "durationMinutes": 60, "notice": "Original, unofficial IELTS-style practice. Scenarios, organisations and study results in these passages are fictional. Format follows published IELTS guidance; difficulty and scores are not calibrated. These are not past-paper questions and cannot establish an IELTS band.", "passages": [{"id": "full-seeds-v1", "title": "The library that grows", "paragraphs": [{"label": "A", "text": "On a shelf inside the fictional town of Mereford’s public library, small paper envelopes sit where a set of outdated travel guides once stood. Each envelope contains seeds and a label recording the variety, the year of collection and the name of the person who supplied it. The collection began with twenty varieties of vegetables donated by a gardening club. Its purpose was not to supply commercial farms, but to help residents experiment with growing food and learn how to save seeds from their own plants. Borrowers could take up to three envelopes per season, and there was no charge."}, {"label": "B", "text": "Calling the service a library created an expectation that everything borrowed would eventually be returned. Seeds make that idea complicated. The original seed disappears as a seed when it develops into a plant, and a useful return consists of seeds produced by that plant or its descendants. Weather, disease or inexperience may prevent such a return. The organisers therefore made returning seeds voluntary. They wanted beginners to participate without fearing a debt they could not repay. A poster explained that a borrower could also contribute by helping to prepare envelopes, translating instructions or sharing an account of an unsuccessful crop."}, {"label": "C", "text": "The first difficulty was identification. Two residents sometimes used different names for what appeared to be the same variety, while other donations shared a name but produced noticeably different plants. Rather than remove uncertain donations immediately, volunteers introduced an additional field on the label: the source of the original seed. This did not settle every question, but it made uncertainty visible. A separate catalogue recorded photographs and growing notes when contributors supplied them. The organisers avoided describing every locally saved seed as uniquely adapted to Mereford; several had been grown in the town for only a single season."}, {"label": "D", "text": "Keeping a variety recognisable can also require attention to how plants reproduce. Some plants can receive pollen from a different variety growing nearby. Their seeds may then produce offspring unlike the plant from which they were collected. For the library’s beginner workshops, volunteers selected varieties for which maintaining a recognisable line was relatively manageable in a small garden. They explained the distinction between saving seeds to preserve a named variety and saving seeds simply to explore what might grow. Both activities could be valuable, but the resulting envelopes needed different descriptions. A surprise in an experimental plot should not become an unannounced surprise for the next borrower."}, {"label": "E", "text": "Storage presented a more ordinary problem. The first envelopes were placed in attractive wooden drawers beside a sunny window. A volunteer who checked conditions found that this location became warmer during the afternoon than a cupboard at the back of the building. The collection was moved to the cupboard, where it was kept dry and away from direct sunlight. At the end of each season, volunteers tested a small sample from selected batches by placing seeds on damp paper and recording how many sprouted. A sample could indicate whether a batch remained usable, but it could not guarantee that every seed in every envelope would grow in a resident’s garden."}, {"label": "F", "text": "As the collection expanded, the organisers considered measuring success through the number of envelopes distributed. That figure was easy to obtain, yet it favoured popular crops and said little about learning. A single envelope used in a school project might generate substantial discussion, while several collected out of curiosity might remain unopened. The annual review therefore reported distribution alongside the number of workshops and voluntary accounts of growing experiences. These accounts were useful examples, not a representative survey of every borrower. The organisers explicitly stated that people who wrote to the library might differ from those who did not."}, {"label": "G", "text": "By its third year, the seed library had formed a partnership with a nearby community garden. The garden provided space to demonstrate seed collection, and the library provided indoor space for winter meetings. Neither organisation had the facilities to maintain every donated variety indefinitely. Instead of promising permanent preservation, they reviewed the collection annually and sought specialist advice when an unusual donation appeared. The project’s strength lay in connecting people, practical experience and clearly described material. Its modest scale was part of its design, rather than evidence that it had failed to become a professional seed bank."}], "questions": [{"id": "fq1", "type": "tfng", "prompt": "The seed library initially contained twenty varieties of vegetables.", "answer": "True", "explanation": "A gives twenty varieties as the initial collection.", "skill": "identifying information", "options": ["True", "False", "Not given"]}, {"id": "fq2", "type": "tfng", "prompt": "Borrowers were required to pay for each envelope.", "answer": "False", "explanation": "A says there was no charge.", "skill": "contradiction", "options": ["True", "False", "Not given"]}, {"id": "fq3", "type": "tfng", "prompt": "Residents could borrow more than three envelopes in a single season.", "answer": "False", "explanation": "A states a limit of three envelopes per season.", "skill": "quantifiers", "options": ["True", "False", "Not given"]}, {"id": "fq4", "type": "tfng", "prompt": "Returning seeds was compulsory for experienced gardeners.", "answer": "False", "explanation": "B says returning seeds was voluntary and gives no compulsory category.", "skill": "quantifiers", "options": ["True", "False", "Not given"]}, {"id": "fq5", "type": "tfng", "prompt": "Most borrowers preferred helping with envelopes to growing plants.", "answer": "Not given", "explanation": "B lists possible contributions but does not compare borrowers’ preferences.", "skill": "not given", "options": ["True", "False", "Not given"]}, {"id": "fq6", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from paragraph C: The new label field identified the source of the _____.", "answer": "original seed", "explanation": "C names the source of the original seed.", "skill": "word-limited completion", "maxWords": 2}, {"id": "fq7", "type": "completion", "prompt": "Complete with ONE WORD from paragraph C: The additional catalogue included growing notes and _____.", "answer": "photographs", "explanation": "C says the catalogue recorded photographs and growing notes.", "skill": "word-limited completion", "maxWords": 1}, {"id": "fq8", "type": "completion", "prompt": "Complete with ONE WORD from paragraph D: Plants may receive _____ from a different variety nearby.", "answer": "pollen", "explanation": "D explains that pollen may come from another variety.", "skill": "word-limited completion", "maxWords": 1}, {"id": "fq9", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from paragraph E: Volunteers tested seeds by putting them on _____.", "answer": "damp paper", "explanation": "E describes testing samples on damp paper.", "skill": "word-limited completion", "maxWords": 2}, {"id": "fq10", "type": "mcq", "prompt": "What limitation of the sprouting test is identified?", "answer": "It cannot guarantee success for every seed in a garden.", "explanation": "E distinguishes a sample indication from a guarantee for every seed.", "skill": "limits of evidence", "options": ["It uses every seed in the collection.", "It cannot guarantee success for every seed in a garden.", "It identifies the exact names of unknown varieties.", "It requires seeds to remain in direct sunlight."]}, {"id": "fq11", "type": "headings", "prompt": "Choose the best heading for paragraph F.", "answer": "Looking beyond a convenient activity count", "explanation": "F explains why distribution figures alone do not capture learning.", "skill": "main idea", "options": ["A ban on school participation", "Looking beyond a convenient activity count", "Solving all questions of seed identity", "Turning gardening accounts into a complete census", "The discovery of an ancient seed variety"]}, {"id": "fq12", "type": "mcq", "prompt": "Why were voluntary growing accounts not treated as a representative survey?", "answer": "People who submitted accounts might differ from other borrowers.", "explanation": "F explicitly notes possible differences between respondents and nonrespondents.", "skill": "sampling", "options": ["The library prohibited unsuccessful stories.", "Every account concerned the same school project.", "People who submitted accounts might differ from other borrowers.", "The accounts were all written before the collection opened."]}, {"id": "fq13", "type": "mcq", "prompt": "What does the final paragraph suggest about the project’s scale?", "answer": "Its limited ambitions suited its resources and purpose.", "explanation": "G presents modest scale as deliberate and explains the limits of permanent preservation.", "skill": "overall meaning", "options": ["It had failed because it was not a professional seed bank.", "Its limited ambitions suited its resources and purpose.", "It could now preserve every donation permanently.", "Its partnership removed the need for specialist advice."]}], "wordCount": 711}, {"id": "full-sounds-v1", "title": "Listening carefully to a city", "paragraphs": [{"label": "A", "text": "Listening to a city seems like a simple way to find out how noisy it is. Yet a sound recording contains more than a single measure of loudness. The same level may come from a passing delivery vehicle, a fountain or a group of people talking. Duration, repetition and context can affect how residents experience it. In the fictional Harbour Sounds project, researchers invited volunteers to make recordings across a coastal city. Their aim was to describe changes in the local sound environment, not to diagnose individuals or determine whether any particular exposure was safe."}, {"label": "B", "text": "The first version of the project allowed volunteers to record whenever and wherever they liked. Within a month, the online map was crowded with samples from parks, cafés and the central waterfront. Industrial streets and some outer districts had few recordings. This imbalance did not show that those districts were quiet. It showed where participating volunteers had chosen to spend time. A map with many points can look comprehensive while reflecting a narrow set of routines. The team therefore separated the number of recordings from the geographical coverage those recordings actually provided."}, {"label": "C", "text": "To obtain more comparable observations, the researchers introduced a fixed route programme. Volunteers visited a set of marked locations at specified times, making a two-minute recording at each. They entered weather conditions and noted temporary events such as construction work. The programme could not remove every difference between visits, but it made several important sources of variation visible. Flexible contributions were still accepted in a separate exploratory collection. Those samples could reveal an unexpected location worth investigating, even though they were not combined directly with the standard route measurements in calculations of change over time."}, {"label": "D", "text": "Equipment created another challenge. Two phones placed side by side could produce different numerical readings because their microphones and software processed sound differently. Asking everyone to buy identical equipment would have excluded some volunteers and increased the project’s cost. Instead, a smaller group used reference recorders at a subset of locations. Their measurements helped the team examine how much results varied between devices. The researchers did not use those comparisons to claim that every phone had become a precision instrument. They restricted some numerical comparisons to recordings made using the reference equipment and used other recordings mainly to identify categories of sound."}, {"label": "E", "text": "Classifying those categories required judgement. A brief metallic sound might be a closing gate, a dropped tool or part of a passing tram. Volunteers could attach a proposed label, but uncertain cases were marked as uncertain rather than forced into a definite category. A second listener reviewed a sample of the labels. Agreement between listeners provided useful information about consistency, although agreement alone could not prove that both had identified the source correctly. For disputed samples, the project retained the recording and the competing descriptions, allowing later reviewers to understand how the classification had been reached."}, {"label": "F", "text": "The project also tested a common assumption about urban improvement. After a small square was redesigned, the number of vehicle sounds in the recordings fell. Some residents welcomed that change, but others said that the new outdoor seating had increased evening conversation. Calling the square simply quieter would have hidden this difference. The researchers reported changes by sound category and time period, alongside comments gathered at a public meeting. They did not treat those comments as the opinion of every resident. Nor did they conclude that the redesign alone had caused all the changes: traffic restrictions elsewhere and the time of year might also have contributed."}, {"label": "G", "text": "Publication required decisions about privacy. Recordings sometimes included conversations that were intelligible even when volunteers had not intended to capture speech. The team instructed participants to avoid recording close to private conversations and reviewed samples before making them public. Where speech remained identifiable, the public version was removed or edited according to the project’s rules. A detailed log recorded those decisions so that another researcher could understand why a sample was absent. The public map consequently contained fewer recordings than the internal catalogue. That difference reflected a deliberate limit, not an unexplained loss of data."}, {"label": "H", "text": "By the end of the trial, Harbour Sounds had produced a less visually crowded map than its first version. Its conclusions were also narrower. However, the remaining information was easier to interpret because the project distinguished exploratory observations, standard measurements and public comments. Citizen participation had expanded what the team could notice, while careful procedures limited what it could claim. The lesson was not that informal observations were worthless. It was that different observations can serve different purposes, and a credible project explains the connection between its evidence and each conclusion."}], "questions": [{"id": "fq14", "type": "headings", "prompt": "Choose the best heading for paragraph B.", "answer": "A crowded map with uneven coverage", "explanation": "B shows that many recording points can reflect volunteer routines rather than coverage of the whole city.", "skill": "main idea", "options": ["A crowded map with uneven coverage", "Managing differences between recording devices", "Restricting publication to protect conversations", "A requirement to buy identical equipment", "The complete disappearance of traffic noise", "Replacing every informal observation", "A history of the city’s waterfront"], "instruction": "Match a heading to the named paragraph. There are more headings than paragraphs; use each heading at most once in questions 14–16."}, {"id": "fq15", "type": "headings", "prompt": "Choose the best heading for paragraph D.", "answer": "Managing differences between recording devices", "explanation": "D describes reference equipment and limits on phone-based numerical comparisons.", "skill": "main idea", "options": ["A crowded map with uneven coverage", "Managing differences between recording devices", "Restricting publication to protect conversations", "A requirement to buy identical equipment", "The complete disappearance of traffic noise", "Replacing every informal observation", "A history of the city’s waterfront"], "instruction": "Match a heading to the named paragraph. There are more headings than paragraphs; use each heading at most once in questions 14–16."}, {"id": "fq16", "type": "headings", "prompt": "Choose the best heading for paragraph G.", "answer": "Restricting publication to protect conversations", "explanation": "G explains review and removal or editing of intelligible speech.", "skill": "main idea", "options": ["A crowded map with uneven coverage", "Managing differences between recording devices", "Restricting publication to protect conversations", "A requirement to buy identical equipment", "The complete disappearance of traffic noise", "Replacing every informal observation", "A history of the city’s waterfront"], "instruction": "Match a heading to the named paragraph. There are more headings than paragraphs; use each heading at most once in questions 14–16."}, {"id": "fq17", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from paragraph C: The standard route required a _____ recording at each location.", "answer": "two-minute", "explanation": "C specifies a two-minute recording. Hyphenated words count as one word.", "skill": "word-limited completion", "maxWords": 2}, {"id": "fq18", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from paragraph C: Volunteers entered _____ and noted temporary events.", "answer": "weather conditions", "explanation": "C lists weather conditions alongside temporary events.", "skill": "word-limited completion", "maxWords": 2}, {"id": "fq19", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from paragraph D: A smaller group collected measurements using _____.", "answer": "reference recorders", "explanation": "D names reference recorders as the comparison equipment.", "skill": "word-limited completion", "maxWords": 2}, {"id": "fq20", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from paragraph E: To examine consistency, a _____ reviewed a sample of labels.", "answer": "second listener", "explanation": "E states that a second listener reviewed a sample.", "skill": "word-limited completion", "maxWords": 2}, {"id": "fq21", "type": "tfng", "prompt": "Agreement between two listeners proved that they had identified a sound correctly.", "answer": "False", "explanation": "E explicitly says agreement alone could not prove correctness.", "skill": "certainty", "options": ["True", "False", "Not given"]}, {"id": "fq22", "type": "tfng", "prompt": "Vehicle sounds became less frequent in recordings after the square was redesigned.", "answer": "True", "explanation": "F says the number of vehicle sounds fell.", "skill": "identifying information", "options": ["True", "False", "Not given"]}, {"id": "fq23", "type": "tfng", "prompt": "Every resident attended the public meeting about the square.", "answer": "Not given", "explanation": "F mentions a public meeting and limits on representativeness; it gives no attendance count.", "skill": "not given", "options": ["True", "False", "Not given"]}, {"id": "fq24", "type": "tfng", "prompt": "The public map included fewer recordings than the internal catalogue.", "answer": "True", "explanation": "G explicitly states this difference.", "skill": "comparisons", "options": ["True", "False", "Not given"]}, {"id": "fq25", "type": "mcq", "prompt": "Why were flexible recordings retained separately?", "answer": "They could suggest places to investigate without being directly comparable standard measurements.", "explanation": "C explains their exploratory value and why they were not combined directly in change calculations.", "skill": "methodology", "options": ["They could suggest places to investigate without being directly comparable standard measurements.", "They were always more accurate than reference recordings.", "They eliminated the need to record weather.", "They contained no possible privacy concerns."]}, {"id": "fq26", "type": "mcq", "prompt": "What is the main conclusion of the passage?", "answer": "Different observations are valuable when the claims made from them match their limitations.", "explanation": "H connects types of evidence with appropriate purposes and conclusions.", "skill": "overall argument", "options": ["Informal observations should always be discarded.", "More recording points always mean a stronger conclusion.", "Different observations are valuable when the claims made from them match their limitations.", "Citizen projects can replace every professional measurement."]}], "wordCount": 772}, {"id": "full-efficiency-v1", "title": "What does greater efficiency actually achieve?", "paragraphs": [{"label": "A", "text": "Efficiency is usually presented as an uncomplicated virtue: complete the same task with less time, energy or material, and everyone benefits. For an individual action, that description may be accurate. Yet when a whole system is involved, the saved resource can be used in ways that alter the final result. A faster process may encourage more activity, or shift costs to a different part of the system. I am not arguing against efficiency. I am arguing that its value cannot be established by measuring one operation in isolation and assuming that all other behaviour will remain unchanged."}, {"label": "B", "text": "Consider a fictional office that replaces slow printers with machines using less electricity per page. If the office prints exactly the same number of pages, electricity use for printing should fall. But cheaper and faster printing may make staff less selective about what they print. A reduction in electricity per page could then coexist with a smaller reduction in total electricity use, or even an increase. The term rebound describes this partial or complete offset of an expected saving when behaviour changes. It does not mean that every efficiency improvement produces an increase in overall consumption. The size and direction of the final change must be investigated."}, {"label": "C", "text": "The correct comparison is often more difficult than a simple before-and-after chart suggests. Suppose printing rises after the new machines arrive. During the same period, the office may have hired additional staff or started a project requiring many printed documents. It would be unreasonable to attribute the entire increase to the printers without considering those changes. Equally, a fall in total printing would not prove that no rebound occurred: without easier printing, the fall might have been greater. The relevant question concerns what would probably have happened without the intervention, an alternative that cannot usually be observed directly."}, {"label": "D", "text": "Some observers respond by demanding perfect evidence before any decision is made. That standard is rarely practical. A more useful response is to state the assumptions behind an estimate and test whether the conclusion changes under plausible alternatives. An office might compare similar departments, record changes in staffing and examine both pages printed and electricity consumed. None of those steps creates a flawless experiment, but together they can make the explanation more credible. Uncertainty should encourage proportionate investigation and transparent reporting, rather than either confident overclaiming or permanent refusal to act."}, {"label": "E", "text": "There is a further distinction between saving a resource and improving a service. A transport app may reduce the time needed to locate a taxi. For a traveller who previously could not find transport, the extra journey may represent a real benefit. From the perspective of total vehicle movement, however, easier access may increase demand. These outcomes are not logically inconsistent. They answer different questions. Describing the app as successful therefore requires an explicit objective. If the aim is accessibility, additional journeys may be welcome; if the aim is reducing traffic, the same change deserves a different assessment."}, {"label": "F", "text": "This is why I distrust a single league table that ranks unlike projects by an undefined measure of efficiency. A repair service, a bus route and an online booking system may serve different populations and pursue different purposes. Collapsing them into one number can hide choices about whose time counts, which costs are included and what quality is expected. Comparisons can still be useful when the boundaries and objectives are clear. The problem is not numerical analysis itself, but the appearance of neutrality when important value judgements have disappeared inside the calculation."}, {"label": "G", "text": "A sensible evaluation should also consider whether a new arrangement becomes difficult to reverse. A school that saves money by sharing specialist equipment across several sites may find the initial calculation attractive. If the arrangement later requires frequent transport, complex booking and long waits, some of the saving may disappear. Those possibilities do not automatically make sharing a mistake. They suggest testing the arrangement at a manageable scale, including the costs of coordination, and retaining a way to change course. A modest pilot can sometimes reveal a practical constraint that an elegant calculation overlooks."}, {"label": "H", "text": "The strongest case for efficiency is therefore a conditional one. We should welcome improvements that deliver a defined benefit with fewer resources, while checking whether altered behaviour, displaced costs or reduced quality weaken that benefit. This requires choosing measures that connect the individual process to the wider purpose. It may result in a less dramatic headline than a claim that a device is twice as efficient. It is also more useful to someone deciding what to fund, adopt or change. The aim is to make efficiency a tool for judgement, rather than a word that ends the discussion."}], "questions": [{"id": "fq27", "type": "ynng", "prompt": "The writer believes every improvement in efficiency is undesirable.", "answer": "No", "explanation": "A explicitly says the writer is not arguing against efficiency.", "skill": "writer claims", "options": ["Yes", "No", "Not given"]}, {"id": "fq28", "type": "ynng", "prompt": "The writer believes a system-wide evaluation should consider changes in behaviour.", "answer": "Yes", "explanation": "A argues that saved resources can change behaviour and final results.", "skill": "writer claims", "options": ["Yes", "No", "Not given"]}, {"id": "fq29", "type": "ynng", "prompt": "The writer believes rebound always increases overall consumption.", "answer": "No", "explanation": "B explicitly rejects the claim that every improvement increases total consumption.", "skill": "quantifiers", "options": ["Yes", "No", "Not given"]}, {"id": "fq30", "type": "ynng", "prompt": "The writer thinks electricity prices will double within five years.", "answer": "Not given", "explanation": "No prediction about future electricity prices appears.", "skill": "not given", "options": ["Yes", "No", "Not given"]}, {"id": "fq31", "type": "completion", "prompt": "Complete with ONE WORD from paragraph B: The offset of an expected saving caused by behavioural change is called _____.", "answer": "rebound", "explanation": "B defines rebound in these terms.", "skill": "word-limited completion", "maxWords": 1}, {"id": "fq32", "type": "completion", "prompt": "Complete with NO MORE THAN TWO WORDS from paragraph C: Printing could increase because the office had hired _____.", "answer": "additional staff", "explanation": "C gives hiring additional staff as a possible alternative explanation.", "skill": "word-limited completion", "maxWords": 2}, {"id": "fq33", "type": "mcq", "prompt": "Why might falling total printing still be consistent with rebound?", "answer": "Without easier printing, printing might have fallen even further.", "explanation": "C states this counterfactual comparison directly.", "skill": "counterfactual reasoning", "options": ["Rebound is defined only by electricity prices.", "A fall is always a measurement error.", "Without easier printing, printing might have fallen even further.", "New printers necessarily cause staff numbers to fall."]}, {"id": "fq34", "type": "mcq", "prompt": "What response to uncertainty does the writer favour?", "answer": "Examine assumptions and test plausible alternative explanations.", "explanation": "D recommends stating assumptions and examining how conclusions change.", "skill": "argument", "options": ["Wait indefinitely for a flawless experiment.", "Treat every before-and-after change as proof.", "Examine assumptions and test plausible alternative explanations.", "Stop recording resource consumption."]}, {"id": "fq35", "type": "headings", "prompt": "Choose the best heading for paragraph E.", "answer": "Different objectives can lead to different judgements", "explanation": "E contrasts accessibility and traffic reduction when evaluating the same transport app.", "skill": "main idea", "options": ["Why taxi use must always fall", "Different objectives can lead to different judgements", "An experiment with office printers", "The superiority of one universal ranking", "How to eliminate every source of uncertainty"]}, {"id": "fq36", "type": "ynng", "prompt": "The writer believes a single ranking can conceal decisions about which costs matter.", "answer": "Yes", "explanation": "F says a combined number may hide choices about whose time and which costs count.", "skill": "writer claims", "options": ["Yes", "No", "Not given"]}, {"id": "fq37", "type": "ynng", "prompt": "The writer thinks numerical comparisons are never useful.", "answer": "No", "explanation": "F says comparisons can be useful when boundaries and objectives are clear.", "skill": "writer claims", "options": ["Yes", "No", "Not given"]}, {"id": "fq38", "type": "completion", "prompt": "Complete with ONE WORD from paragraph G: A trial of shared equipment should include the costs of _____.", "answer": "coordination", "explanation": "G explicitly calls for including the costs of coordination.", "skill": "word-limited completion", "maxWords": 1}, {"id": "fq39", "type": "mcq", "prompt": "Why does the writer favour a manageable pilot for sharing equipment?", "answer": "It can expose practical difficulties before a wider commitment.", "explanation": "G says a modest pilot can reveal constraints overlooked by a calculation and preserve the ability to change course.", "skill": "purpose", "options": ["It guarantees that the scheme will fail.", "It removes the need to consider service quality.", "It can expose practical difficulties before a wider commitment.", "It proves that shared equipment always saves money."]}, {"id": "fq40", "type": "mcq", "prompt": "Which statement best expresses the writer’s overall position?", "answer": "Efficiency should be evaluated against a defined purpose and its wider consequences.", "explanation": "H supports efficiency conditionally, checking behaviour, costs and quality against a defined benefit.", "skill": "overall argument", "options": ["The most impressive headline is the best basis for investment.", "Efficiency should be evaluated against a defined purpose and its wider consequences.", "A process should be assessed without considering its users.", "Resource savings are impossible in any large system."]}], "wordCount": 775}], "wordCount": 2258}, "drills": [{"id": "academic-drill-1-v1", "type": "mcq", "prompt": "A study found that frequent readers had larger vocabularies. Which statement preserves the strength of that evidence?", "options": ["Reading was associated with a larger vocabulary.", "Reading was proved to be the only cause of a larger vocabulary.", "Every frequent reader had a larger vocabulary than every other person.", "Vocabulary cannot influence reading habits."], "answer": "Reading was associated with a larger vocabulary.", "explanation": "An association does not by itself establish a cause or exclude other explanations.", "skill": "association and causation"}, {"id": "academic-drill-2-v1", "type": "mcq", "prompt": "Choose the closest paraphrase of: The policy may reduce congestion.", "options": ["The policy is certain to eliminate congestion.", "The policy has the potential to reduce congestion.", "The policy has already removed congestion.", "The policy cannot affect congestion."], "answer": "The policy has the potential to reduce congestion.", "explanation": "May expresses possibility; it does not promise a result.", "skill": "hedging"}, {"id": "academic-drill-3-v1", "type": "mcq", "prompt": "Complete: _____ the sample was small, the pattern was consistent across all three visits.", "options": ["Although", "Despite", "Because of", "Whereas of"], "answer": "Although", "explanation": "Although introduces a clause with a subject and verb. Despite normally takes a noun phrase or -ing form.", "skill": "contrast grammar"}, {"id": "academic-drill-4-v1", "type": "mcq", "prompt": "Complete: _____ its small sample, the study provided useful preliminary evidence.", "options": ["Although", "Despite", "Even though", "Whereas"], "answer": "Despite", "explanation": "Its small sample is a noun phrase, so despite fits. Although would require a clause.", "skill": "contrast grammar"}, {"id": "academic-drill-5-v1", "type": "mcq", "prompt": "Choose the sentence that describes a change from 20% to 30% accurately.", "options": ["The share rose by 10 percentage points.", "The share rose by 10 per cent relative to its initial value.", "The share doubled.", "The share fell by one third."], "answer": "The share rose by 10 percentage points.", "explanation": "30 minus 20 is 10 percentage points. The relative increase is 50%, a different measure.", "skill": "describing data"}, {"id": "academic-drill-6-v1", "type": "mcq", "prompt": "Complete: The proportion of journeys made by bicycle _____ from 12% to 18%.", "options": ["rose", "raised", "was raising", "arose"], "answer": "rose", "explanation": "Rise is intransitive: the proportion rose. Raise normally needs an object: someone raised a value.", "skill": "rise and raise"}, {"id": "academic-drill-7-v1", "type": "mcq", "prompt": "Choose the closest paraphrase of: Few participants completed every task.", "options": ["Almost all participants completed every task.", "A small number of participants completed every task.", "No participant completed any task.", "All participants completed a small number of tasks."], "answer": "A small number of participants completed every task.", "explanation": "Few refers to a small number; it does not mean none, and every task is not the same as any task.", "skill": "quantifiers"}, {"id": "academic-drill-8-v1", "type": "mcq", "prompt": "Complete: The researchers _____ a distinction between reported preferences and observed behaviour.", "options": ["made", "did", "took", "held"], "answer": "made", "explanation": "Make a distinction is the standard collocation.", "skill": "academic collocations"}, {"id": "academic-drill-9-v1", "type": "mcq", "prompt": "Complete: The explanation is consistent _____ the evidence, but it is not the only possible explanation.", "options": ["with", "to", "for", "by"], "answer": "with", "explanation": "Consistent with means compatible with. Compatibility does not establish uniqueness.", "skill": "academic collocations"}, {"id": "academic-drill-10-v1", "type": "mcq", "prompt": "Choose the sentence that preserves the meaning: Not all participants improved.", "options": ["No participants improved.", "Every participant improved.", "At least one participant did not improve.", "Only one participant improved."], "answer": "At least one participant did not improve.", "explanation": "Not all rejects a universal claim; it does not tell us how many improved.", "skill": "logical quantifiers"}, {"id": "academic-drill-11-v1", "type": "mcq", "prompt": "Complete: There were _____ errors in the second attempt than in the first.", "options": ["fewer", "less", "little", "much"], "answer": "fewer", "explanation": "Errors is a plural count noun, so fewer is the appropriate comparative.", "skill": "count and noncount nouns"}, {"id": "academic-drill-12-v1", "type": "mcq", "prompt": "Complete: The new method requires _____ equipment than the old one.", "options": ["fewer", "less", "many", "a few"], "answer": "less", "explanation": "Equipment is normally an uncountable noun in this use.", "skill": "count and noncount nouns"}, {"id": "academic-drill-13-v1", "type": "mcq", "prompt": "Choose the best paraphrase of: The findings apply only to the schools included in the study.", "options": ["The findings have been confirmed in every school.", "The findings should not automatically be generalised to other schools.", "The schools were selected because the findings were already known.", "The findings are necessarily false outside the study."], "answer": "The findings should not automatically be generalised to other schools.", "explanation": "Limited evidence does not justify automatic generalisation; nor does it prove the opposite elsewhere.", "skill": "scope of evidence"}, {"id": "academic-drill-14-v1", "type": "mcq", "prompt": "Complete: Revenue increased, _____ operating costs remained stable.", "options": ["whereas", "because of", "despite", "in spite"], "answer": "whereas", "explanation": "Whereas links two clauses that contrast different trends.", "skill": "contrast grammar"}, {"id": "academic-drill-15-v1", "type": "mcq", "prompt": "Choose the most precise sentence for a chart showing attendance falling slowly from 80 to 72 over five years.", "options": ["Attendance plummeted to almost nothing.", "Attendance declined gradually from 80 to 72.", "Attendance fluctuated sharply between 80 and 72 each month.", "Attendance remained completely unchanged."], "answer": "Attendance declined gradually from 80 to 72.", "explanation": "Gradually describes a slow change. The other options add unsupported size, fluctuation or stability.", "skill": "describing trends"}, {"id": "academic-drill-16-v1", "type": "mcq", "prompt": "Complete: Several factors may account _____ the difference between the two groups.", "options": ["for", "to", "with", "at"], "answer": "for", "explanation": "Account for means explain in this context.", "skill": "academic collocations"}, {"id": "academic-drill-17-v1", "type": "mcq", "prompt": "Choose the closest paraphrase of: Unless access improves, participation is unlikely to rise.", "options": ["Participation is unlikely to rise if access does not improve.", "Participation will rise regardless of access.", "Improved access guarantees that everyone participates.", "Participation must fall whenever access improves."], "answer": "Participation is unlikely to rise if access does not improve.", "explanation": "Unless means if not. The sentence makes no guarantee that improved access is sufficient.", "skill": "conditional meaning"}, {"id": "academic-drill-18-v1", "type": "mcq", "prompt": "Complete: The committee recommended _____ the trial before expanding it.", "options": ["evaluating", "to evaluate", "evaluate", "that evaluating"], "answer": "evaluating", "explanation": "Recommend can be followed by an -ing form: recommended evaluating the trial.", "skill": "verb patterns"}, {"id": "academic-drill-19-v1", "type": "mcq", "prompt": "Choose the most accurate paraphrase of: The results challenge the assumption that price is the only barrier.", "options": ["The results prove that price never matters.", "The results suggest that barriers other than price may matter.", "The results confirm that all barriers are financial.", "The results say that every person has the same barrier."], "answer": "The results suggest that barriers other than price may matter.", "explanation": "Challenging the claim that price is the only barrier does not remove price as one possible factor.", "skill": "paraphrase"}, {"id": "academic-drill-20-v1", "type": "mcq", "prompt": "Complete: The experiment provides evidence _____ the proposed explanation.", "options": ["in support of", "in support to", "on support of", "by support for"], "answer": "in support of", "explanation": "In support of is the conventional phrase. Evidence can support an explanation without proving it conclusively.", "skill": "academic collocations"}, {"id": "academic-drill-21-v1", "type": "mcq", "prompt": "Choose the sentence with the clearest reference: Two surveys compared transport costs and reliability. _____ was the stronger concern among respondents.", "options": ["Reliability", "It", "This thing", "They"], "answer": "Reliability", "explanation": "Naming reliability removes the ambiguity about which of the two factors is meant.", "skill": "coherence"}, {"id": "academic-drill-22-v1", "type": "mcq", "prompt": "Complete: By the end of 2020, the centre _____ three new classrooms.", "options": ["had opened", "has open", "will opened", "opening"], "answer": "had opened", "explanation": "Past perfect locates the completed opening before a specified point in the past.", "skill": "past time reference"}, {"id": "academic-drill-23-v1", "type": "mcq", "prompt": "Choose the closest paraphrase of: The intervention had little effect on total demand.", "options": ["Total demand changed only slightly as a result of the intervention.", "The intervention eliminated all demand.", "Demand increased dramatically because of the intervention.", "The intervention was never implemented."], "answer": "Total demand changed only slightly as a result of the intervention.", "explanation": "Little effect indicates a small impact, not necessarily zero and not a large increase.", "skill": "degree and meaning"}, {"id": "academic-drill-24-v1", "type": "mcq", "prompt": "Complete: The survey cannot establish causation; _____, it can identify patterns worth investigating.", "options": ["nevertheless", "therefore", "because", "unless"], "answer": "nevertheless", "explanation": "Nevertheless marks a contrast between a limitation and a continuing useful role.", "skill": "linking ideas"}], "writing": [{"id": "writing-transport-table-v1", "kind": "task1", "title": "Commuting choices", "prompt": "The table shows the percentage of commuters using their main travel mode in the fictional city of Westhaven in 2005 and 2025. Describe the main features and make relevant comparisons. Use full sentences and your own words. Write at least 150 words.", "durationMinutes": 20, "minWords": 150, "visual": {"type": "table", "caption": "Main commuting mode in Westhaven (% of commuters). Each year totals 100%. Original fictional data.", "columns": ["Main mode", "2005 (%)", "2025 (%)"], "rows": [["Car", 55, 38], ["Bus", 20, 24], ["Bicycle", 8, 20], ["Walking", 12, 13], ["Other", 5, 5]]}, "shortPractice": "In eight minutes, identify the biggest changes, then write your own overview and one comparison paragraph. Save it as partial practice, not a complete Task 1."}, {"id": "writing-museum-line-v1", "kind": "task1", "title": "Museum visits over time", "prompt": "The chart shows annual visits to three fictional museums between 2015 and 2025. Describe the main features and compare the museums where appropriate. Use full sentences and your own words. Write at least 150 words.", "durationMinutes": 20, "minWords": 150, "visual": {"type": "line", "caption": "Annual museum visits (thousands). Original fictional data; lines connect recorded years.", "columns": ["Year", "Science museum", "History museum", "Art museum"], "rows": [[2015, 80, 120, 60], [2017, 95, 115, 70], [2019, 110, 110, 90], [2021, 130, 100, 100], [2023, 150, 105, 115], [2025, 170, 110, 125]]}, "shortPractice": "In eight minutes, select an overall pattern and two useful comparisons. Write a short report section using the correct units; do not invent reasons for the changes."}, {"id": "writing-recycling-process-v1", "kind": "task1", "title": "From used paper to new sheets", "prompt": "The diagram presents a simplified process for turning used office paper into new paper sheets. Describe the main stages and their sequence in your own words. Write at least 150 words.", "durationMinutes": 20, "minWords": 150, "visual": {"type": "process", "caption": "A simplified fictional paper-recycling process. Arrows follow the numbered sequence.", "columns": ["Stage", "Input or action", "Output or next step"], "rows": [["1", "Collect used office paper", "Collected paper"], ["2", "Sort paper and remove plastic and metal", "Sorted paper; rejected materials leave the process"], ["3", "Add water and mix", "Pulp (a wet mixture of separated paper fibres)"], ["4", "Filter the pulp", "Cleaned pulp; remaining contaminants leave the process"], ["5", "Spread pulp onto a moving mesh", "Excess water drains away"], ["6", "Press and heat the material", "Dry continuous paper"], ["7", "Cut the paper", "Finished sheets"]]}, "shortPractice": "In eight minutes, plan the beginning, end and main phases, then describe several connected stages. Use the supplied process only; do not add unshown chemicals or machinery."}, {"id": "writing-library-map-v1", "kind": "task1", "title": "Changes to a town library", "prompt": "The two plans show the ground floor of a fictional town library in 2010 and after renovation in 2025. Describe the principal changes and relevant features that remained the same. Write at least 150 words.", "durationMinutes": 20, "minWords": 150, "visual": {"type": "map", "caption": "Library plans. North is at the top; the entrance remains centred on the south wall. The building outline is unchanged. Each row identifies one location in the plan.", "columns": ["Location", "2010", "2025"], "rows": [["North-west", "Reference shelves", "Group study room"], ["North-east", "Reading room", "Reading room"], ["West centre", "Book shelves", "Book shelves"], ["East centre", "Computer room", "Digital studio"], ["South-west", "Reception desk", "Self-service kiosks"], ["South-east", "Storage room", "Café"], ["South centre", "Entrance", "Entrance"]]}, "shortPractice": "In eight minutes, identify what changed and what stayed the same, then write an overview and a paragraph describing two changes. Use the plan’s directions rather than inventing measurements."}, {"id": "writing-task2-university-v1", "kind": "task2", "title": "The purpose of university", "prompt": "Some people believe that universities should concentrate on preparing students for specific careers. Others believe that universities should give students a broad education. Discuss both views and give your own opinion. Support your ideas with reasons and examples. Write at least 250 words.", "durationMinutes": 40, "minWords": 250, "shortPractice": "In eight minutes, decide your position, identify a fair argument for each view, and write one paragraph that develops a reason and an example."}, {"id": "writing-task2-transport-v1", "kind": "task2", "title": "Funding urban transport", "prompt": "Governments should spend more money improving public transport than building new roads. To what extent do you agree or disagree? Support your position with reasons and examples. Write at least 250 words.", "durationMinutes": 40, "minWords": 250, "shortPractice": "In eight minutes, state the extent of your agreement and develop one reason. Consider a limitation or exception rather than only listing benefits."}, {"id": "writing-task2-waste-v1", "kind": "task2", "title": "Replacing household products", "prompt": "Many household products are replaced even when they could be repaired. What are the main reasons for this, and what measures could encourage more repairs? Support your ideas with reasons and examples. Write at least 250 words.", "durationMinutes": 40, "minWords": 250, "shortPractice": "In eight minutes, connect one plausible cause with one measure that addresses that cause, then explain the connection in a paragraph."}, {"id": "writing-task2-online-v1", "kind": "task2", "title": "Online higher education", "prompt": "More university courses are becoming available entirely online. Do the advantages of this development outweigh the disadvantages? Support your answer with reasons and examples. Write at least 250 words.", "durationMinutes": 40, "minWords": 250, "shortPractice": "In eight minutes, identify one substantial advantage and one substantial disadvantage, decide which carries more weight, and explain why in your own words."}], "speaking": [{"id": "speaking-learning-v1", "title": "Learning something useful", "part1": ["What do you enjoy studying at the moment?", "Do you prefer to study alone or with other people? Why?", "What kind of place helps you concentrate?", "Has the way you organise your studies changed?"], "part2": {"prompt": "Describe a useful skill you learned outside a formal lesson.", "bullets": ["what the skill was", "how you learned it", "what was difficult about learning it", "and explain why the skill has been useful to you."]}, "part3": ["Why do some practical skills take longer to learn than people expect?", "What are the advantages and limitations of learning from online videos?", "Should schools devote more time to practical skills? Why or why not?", "How can people judge whether advice about learning is reliable?"], "timing": {"part1Minutes": "4–5", "part2PreparationSeconds": 60, "part2SpeakingSeconds": 120, "part3Minutes": "4–5", "fullMinutes": "11–14"}, "notice": "Original practice prompts. A timer or typed answer does not reproduce a live examiner interview. Typed answers cannot establish pronunciation or an overall Speaking band."}, {"id": "speaking-place-v1", "title": "A place that works well", "part1": ["What kinds of public places do you use regularly?", "Do you prefer busy places or quiet places?", "Is there a place near you that you would like to improve?", "How do you usually decide where to spend your free time?"], "part2": {"prompt": "Describe a public place that you think is well designed.", "bullets": ["where it is", "what people do there", "which features you particularly notice", "and explain why you think its design works well."]}, "part3": ["Who should be involved in decisions about public spaces?", "Can a space work well for young people and older people at the same time?", "What difficulties arise when cities adapt old buildings for new uses?", "How should a city judge whether a redesigned public space is successful?"], "timing": {"part1Minutes": "4–5", "part2PreparationSeconds": 60, "part2SpeakingSeconds": 120, "part3Minutes": "4–5", "fullMinutes": "11–14"}, "notice": "Original practice prompts. A timer or typed answer does not reproduce a live examiner interview. Typed answers cannot establish pronunciation or an overall Speaking band."}, {"id": "speaking-information-v1", "title": "Information that changed your view", "part1": ["What do you usually enjoy reading?", "Do you prefer reading on a screen or on paper? Why?", "How do you choose an article or programme to spend time on?", "Do you often discuss things you have read with other people?"], "part2": {"prompt": "Describe an article, book or programme that made you think differently about a topic.", "bullets": ["what it was about", "how you found it", "what idea you remember", "and explain how or why it changed your thinking."]}, "part3": ["What makes an explanation convincing?", "Why might two people interpret the same information differently?", "Should publishers simplify complex topics for a wide audience?", "How can people recognise the difference between evidence and an opinion?"], "timing": {"part1Minutes": "4–5", "part2PreparationSeconds": 60, "part2SpeakingSeconds": 120, "part3Minutes": "4–5", "fullMinutes": "11–14"}, "notice": "Original practice prompts. A timer or typed answer does not reproduce a live examiner interview. Typed answers cannot establish pronunciation or an overall Speaking band."}], "sources": [{"title": "Official IELTS Academic Reading format", "url": "https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-reading"}, {"title": "Official IELTS Academic Writing format", "url": "https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-writing"}, {"title": "Official IELTS Academic Speaking format", "url": "https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-speaking"}, {"title": "Official IELTS Academic sample questions", "url": "https://ielts.org/take-a-test/preparation-resources/sample-test-questions/academic-test"}]};root.IELTS_CONTENT=content;if(typeof module==='object'&&module.exports)module.exports=content;})(typeof window!=='undefined'?window:globalThis);
